(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-l3"] = {"id":"x04-l3","patterns":["L3-humanities","PARA-opinion"],"title":{"en":"Listening Part 3: planning a presentation","tr":"Listening Part 3: bir sunum planlamak","fa":"Listening Part 3: برنامه‌ریزی یک ارائه"},"objective":{"en":"In this lesson you will learn to follow two students planning a presentation: answer three multiple-choice questions about their decisions, and match seven features to the opinions they agree on from a box of nine.","tr":"Bu derste bir sunum planlayan iki öğrenciyi takip etmeyi öğreneceksin: kararlarıyla ilgili üç çoktan seçmeli soruyu cevaplayacak ve yedi özelliği dokuz seçenekli bir kutudan üzerinde anlaştıkları görüşlerle eşleştireceksin.","fa":"در این درس یاد می‌گیری صحبت دو دانشجو را که ارائه‌ای را برنامه‌ریزی می‌کنند دنبال کنی: به سه سؤال چندگزینه‌ای درباره‌ی تصمیم‌هایشان جواب بدهی و هفت ویژگی را به نظرهایی که روی آن‌ها توافق دارند از یک کادر نُه‌تایی وصل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 3: planning a presentation","tr":"Listening Part 3: bir sunum planlamak","fa":"Listening Part 3: برنامه‌ریزی یک ارائه"},"objective":{"en":"In this lesson you will learn to follow two students planning a presentation: answer three multiple-choice questions about their decisions, and match seven features to the opinions they agree on from a box of nine.","tr":"Bu derste bir sunum planlayan iki öğrenciyi takip etmeyi öğreneceksin: kararlarıyla ilgili üç çoktan seçmeli soruyu cevaplayacak ve yedi özelliği dokuz seçenekli bir kutudan üzerinde anlaştıkları görüşlerle eşleştireceksin.","fa":"در این درس یاد می‌گیری صحبت دو دانشجو را که ارائه‌ای را برنامه‌ریزی می‌کنند دنبال کنی: به سه سؤال چندگزینه‌ای درباره‌ی تصمیم‌هایشان جواب بدهی و هفت ویژگی را به نظرهایی که روی آن‌ها توافق دارند از یک کادر نُه‌تایی وصل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Box","tr":"Kutu","fa":"کادر"},"value":"A-I"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: offices of the future","tr":"Bu sınav: geleceğin ofisleri","fa":"این آزمون: دفترهای کار آینده"},"intro":{"en":"Part 3 is students discussing their work. Presentations and assignments on society, design and the way we live are among the commonest topics. The students suggest, disagree and finally decide.","tr":"Part 3, öğrencilerin çalışmalarını konuştuğu bölümdür. Toplum, tasarım ve yaşama biçimimiz üzerine sunumlar ve ödevler en yaygın konulardandır. Öğrenciler önerir, itiraz eder ve sonunda karar verir.","fa":"Part 3 گفتگوی دانشجوها درباره‌ی کارشان است. ارائه‌ها و تکلیف‌هایی درباره‌ی جامعه، طراحی و شیوه‌ی زندگی ما از رایج‌ترین موضوع‌هایند. دانشجوها پیشنهاد می‌دهند، مخالفت می‌کنند و آخر سر تصمیم می‌گیرند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-l3-ctx","exam":true,"patterns":["L3-humanities","PARA-opinion"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Preparing a presentation","tr":"Bir sunum hazırlamak","fa":"آماده کردن یک ارائه"},"asks":{"en":"Two students plan a presentation on offices of the future: why they chose the topic, how to organise it and what visuals to use, then what they will say about seven features of future offices.","tr":"İki öğrenci geleceğin ofisleri üzerine bir sunum planlıyor: konuyu neden seçtikleri, nasıl düzenleyecekleri ve hangi görselleri kullanacakları, sonra geleceğin ofislerinin yedi özelliği hakkında ne söyleyecekleri.","fa":"دو دانشجو ارائه‌ای درباره‌ی دفترهای کار آینده را برنامه‌ریزی می‌کنند: چرا موضوع را انتخاب کردند، چطور مرتبش کنند و چه تصویرهایی به کار ببرند، و بعد درباره‌ی هفت ویژگی دفترهای آینده چه بگویند."},"fields":["Why this topic","Structure","Visuals","Seven features"],"words":[{"a":"organise","b":"decide the order / give it a shape","tr":"düzenlemek","fa":"سازمان دادن"},{"a":"in time order","b":"past, present, future","tr":"zaman sırasıyla","fa":"به ترتیب زمان"},{"a":"visuals","b":"pictures, charts, clips","tr":"görseller","fa":"تصویرها و نمودارها"},{"a":"eat into","b":"use up part of","tr":"... bir kısmını yemek","fa":"بخشی از ... را گرفتن"},{"a":"just for show","b":"only to impress people","tr":"sadece gösteriş için","fa":"فقط برای نمایش"},{"a":"a gimmick","b":"a trick to get attention","tr":"dikkat çekme numarası","fa":"ترفند تبلیغاتی"},{"a":"the evidence is mixed","b":"some studies agree, others don’t","tr":"kanıtlar çelişkili","fa":"شواهد ضدونقیض‌اند"},{"a":"cut their bills","b":"pay less","tr":"faturalarını düşürmek","fa":"قبض‌ها را کم کردن"},{"a":"realistically","b":"being practical","tr":"gerçekçi olarak","fa":"واقع‌بینانه"},{"a":"soundproof","b":"no noise gets in or out","tr":"ses yalıtımlı","fa":"عایق صدا"},{"a":"focus","b":"concentrate","tr":"odaklanmak","fa":"تمرکز کردن"}],"traps":[{"en":"\"Some people say...\" or \"people claim...\" introduces a view the students may reject. The answer is the point they agree on in the end.","tr":"\"Some people say...\" ya da \"people claim...\" öğrencilerin reddedebileceği bir görüş getirir. Cevap, sonunda üzerinde anlaştıkları noktadır.","fa":"«Some people say...» یا «people claim...» نظری را می‌آورد که شاید دانشجوها ردش کنند. جواب نکته‌ای است که آخر سر روی آن توافق می‌کنند."},{"en":"A true detail is not always the main point: \"children love the new park, but the real winners are the parents\". The box option must match the main point.","tr":"Doğru bir ayrıntı her zaman ana nokta değildir: \"çocuklar yeni parkı çok seviyor ama asıl kazananlar ebeveynler\". Kutu seçeneği ana noktayla eşleşmeli.","fa":"یک جزئیات درست همیشه نکته‌ی اصلی نیست: «بچه‌ها پارک جدید را خیلی دوست دارند، اما برنده‌ی اصلی پدر و مادرها هستند». گزینه‌ی کادر باید با نکته‌ی اصلی جور باشد."}],"example":{"lines":[["Student 1","Some people say green walls are just decoration."],["Student 2","Maybe, but they really do clean the air. That’s the main point for me."],["Student 1","Yes, let’s say that."]],"item":"What do they say about green walls? A They are only decoration. B They clean the air. C They are expensive.","answer":"B","why":{"en":"\"Some people say\" gives A; the students agree on cleaning the air.","tr":"\"Bazıları ... diyor\" A’yı verir; öğrenciler havayı temizlemesinde anlaşıyor.","fa":"«بعضی‌ها می‌گویند» A را می‌دهد؛ دانشجوها روی تمیز کردن هوا توافق می‌کنند."}}},{"id":"L3-tech","ctx":["L3-tech","L3-science","L3-humanities"],"title":{"en":"Technology, design and cities","tr":"Teknoloji, tasarım ve şehirler","fa":"فناوری، طراحی و شهرها"},"asks":{"en":"Two students, sometimes with a tutor, plan or review a project on homes of the future, machines at work, sport technology or transport in cities. Questions ask what they decide, what they think of a source or a method, what went wrong and what they will do next.","tr":"İki öğrenci, bazen bir hocayla, geleceğin evleri, işyerinde makineler, spor teknolojisi ya da şehir içi ulaşım üzerine bir projeyi planlar ya da değerlendirir. Sorular neye karar verdiklerini, bir kaynak ya da yöntem hakkında ne düşündüklerini, neyin ters gittiğini ve sırada ne yapacaklarını sorar.","fa":"دو دانشجو، گاهی با یک استاد، پروژه‌ای درباره‌ی خانه‌های آینده، ماشین‌ها در محیط کار، فناوری ورزشی یا حمل‌ونقل شهری را برنامه‌ریزی یا بررسی می‌کنند. سؤال‌ها می‌پرسند به چه تصمیمی می‌رسند، درباره‌ی یک منبع یا روش چه فکر می‌کنند، چه چیزی خراب شد و قدم بعدی‌شان چیست."},"fields":["What is the main advantage of the scheme?","What problem do the students identify?","Which TWO changes do they predict?","What do they decide to put on the slides?"],"words":[{"a":"scheme","b":"the system / the programme","tr":"sistem, uygulama","fa":"طرح"},{"a":"automation","b":"machines doing the work","tr":"otomasyon","fa":"خودکارسازی"},{"a":"device","b":"the gadget / the machine","tr":"cihaz","fa":"دستگاه"},{"a":"urban","b":"in cities","tr":"kentsel","fa":"شهری"},{"a":"infrastructure","b":"roads, pipes and cables","tr":"altyapı","fa":"زیرساخت"},{"a":"efficient","b":"saves time or energy","tr":"verimli","fa":"کارآمد"},{"a":"drawback","b":"the downside","tr":"dezavantaj","fa":"عیب"},{"a":"predict","b":"expect in the future","tr":"öngörmek","fa":"پیش‌بینی کردن"},{"a":"users","b":"the people who use it","tr":"kullanıcılar","fa":"کاربرها"},{"a":"maintenance","b":"keeping it working","tr":"bakım","fa":"نگهداری"},{"a":"cost-effective","b":"good value for the money","tr":"uygun maliyetli","fa":"به‌صرفه"},{"a":"replace","b":"take the place of","tr":"yerini almak","fa":"جایگزین شدن"}],"traps":[{"en":"Advantages for whom: the scheme helps users but costs the council more. Read who the question is about.","tr":"Kimin için avantaj: sistem kullanıcılara yarar ama belediyeye daha pahalıya gelir. Sorunun kimi sorduğunu oku.","fa":"مزیت برای چه کسی: طرح به کاربرها کمک می‌کند ولی برای شهرداری گران‌تر تمام می‌شود. ببین سؤال درباره‌ی چه کسی است."},{"en":"Predictions: \"some people say X, but I think Y is more likely\". The speaker’s own view comes second.","tr":"Tahminler: \"bazıları X diyor ama bence Y daha olası\". Konuşanın kendi görüşü ikinci gelir.","fa":"پیش‌بینی‌ها: «بعضی‌ها می‌گویند X، ولی به نظر من Y محتمل‌تر است». نظر خود گوینده دوم می‌آید."}],"example":{"lines":[["Student A","Most people think bike-sharing is popular because it’s cheap."],["Student B","The survey says otherwise."],["Student B","People mainly use it because it’s quicker than the bus in the rush hour."]],"item":"Why do most people use the scheme?  A It is cheap.   B It is quicker in the rush hour.   C It is healthy.","answer":"B","why":{"en":"\"Cheap\" is what most people think. \"The survey says otherwise\": speed in the rush hour.","tr":"\"Ucuz\" çoğu insanın sandığı şey. \"The survey says otherwise\": yoğun saatte hız.","fa":"«ارزان» چیزی است که بیشتر مردم فکر می‌کنند. «The survey says otherwise»: سرعت در ساعت شلوغی."}},"general":true,"patterns":["L3-science","L3-humanities"],"often":{"pattern":"L3-science","n":19,"of":40,"label":{"en":"Comes up often in the real exam: 19 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 19’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۹ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three decisions, then seven features","tr":"Üç karar, sonra yedi özellik","fa":"سه تصمیم، بعد هفت ویژگی"},"body":{"en":"Questions 21-23 are multiple choice, A-C. After a short break, Questions 24-30 list seven features: choose SEVEN answers from a box of nine, A-I, each letter once, so two are left over.","tr":"Soru 21-23 çoktan seçmelidir, A-C. Kısa bir aradan sonra Soru 24-30 yedi özellik sıralar: A-I arasındaki dokuz seçenekten YEDİ cevap seç, her harf bir kez; ikisi artar.","fa":"سؤال‌های ۲۱ تا ۲۳ چندگزینه‌ای‌اند، A تا C. بعد از یک مکث کوتاه، سؤال‌های ۲۴ تا ۳۰ هفت ویژگی را فهرست می‌کنند: از کادر نُه‌تایی A تا I هفت جواب انتخاب کن، هر حرف یک بار، پس دو تا اضافه می‌مانند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Suggestion, reaction, decision","tr":"Öneri, tepki, karar","fa":"پیشنهاد، واکنش، تصمیم"},"steps":[{"en":"For each question, listen for three moves: one student suggests, the other reacts, and they decide.","tr":"Her soru için üç hamleyi dinle: bir öğrenci önerir, diğeri tepki verir ve karar verirler.","fa":"برای هر سؤال به سه حرکت گوش بده: یک دانشجو پیشنهاد می‌دهد، دیگری واکنش نشان می‌دهد و تصمیم می‌گیرند."},{"en":"Decision words: \"Fair enough\", \"Yes, let’s say that\", \"Agreed\", \"Photos it is\".","tr":"Karar kelimeleri: \"Fair enough\", \"Yes, let’s say that\", \"Agreed\", \"Photos it is\".","fa":"کلمه‌های تصمیم: «Fair enough»، «Yes, let’s say that»، «Agreed»، «Photos it is»."},{"en":"In the box task, write a letter only after the decision, then cross it out.","tr":"Kutu görevinde harfi ancak karardan sonra yaz, sonra üstünü çiz.","fa":"در تمرین کادر، فقط بعد از تصمیم حرف را بنویس و بعد خطش بزن."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Other people’s views","tr":"Başkalarının görüşleri","fa":"نظرِ دیگران"},"body":{"en":"Two of the box options are usually ideas the students mention and reject, often introduced by \"some people say\", \"people claim\" or \"apparently\". Choose the option that matches what the students conclude.","tr":"Kutudaki seçeneklerden ikisi genelde öğrencilerin söz edip reddettiği fikirlerdir; çoğu zaman \"some people say\", \"people claim\" ya da \"apparently\" ile gelir. Öğrencilerin vardığı sonuca uyan seçeneği seç.","fa":"دو گزینه از کادر معمولاً ایده‌هایی‌اند که دانشجوها اسمشان را می‌برند و ردشان می‌کنند، اغلب با «some people say»، «people claim» یا «apparently». گزینه‌ای را انتخاب کن که با نتیجه‌ی دانشجوها جور است."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One decision, step by step","tr":"Bir karar, adım adım","fa":"یک تصمیم، قدم به قدم"},"instruction":"How will the students start their talk? A with a question  B with a story  C with some figures","item":"Choose A, B or C.","lines":[["Student 1","Shall we start with some figures?"],["Student 2","Numbers at the start can be a bit dry. A short story about a real person would grab their attention."],["Student 1","Good idea. Let’s do that."]],"answer":"B","walk":[{"en":"C is suggested first.","tr":"Önce C öneriliyor.","fa":"اول C پیشنهاد می‌شود."},{"en":"The other student reacts against it and suggests a story.","tr":"Diğer öğrenci buna karşı çıkıp bir hikâye öneriyor.","fa":"دانشجوی دیگر مخالفت می‌کند و یک داستان پیشنهاد می‌دهد."},{"en":"\"Good idea. Let’s do that\" is the decision: B.","tr":"\"İyi fikir. Öyle yapalım\" karardır: B.","fa":"«ایده‌ی خوبی است. همین کار را بکنیم» تصمیم است: B."}]},"quick":{"prompt":"\"People claim these chairs are bad for your back.\" \"Actually, the studies show the opposite: they help.\" What do the students say about the chairs?","options":["They are good for your back.","They are bad for your back.","Nobody knows."],"correct":0,"why":{"en":"\"People claim\" is the view they reject; \"actually, the studies show... they help\".","tr":"\"People claim\" reddettikleri görüştür; \"aslında araştırmalar... yardımcı olduklarını gösteriyor\".","fa":"«people claim» نظری است که رد می‌کنند؛ «در واقع پژوهش‌ها نشان می‌دهند... کمک می‌کنند»."}},"remember":{"en":"Wait for the decision, and match the box to what the students conclude, not to what other people say.","tr":"Kararı bekle ve kutuyu başkalarının söylediğiyle değil, öğrencilerin vardığı sonuçla eşleştir.","fa":"منتظر تصمیم بمان و کادر را با نتیجه‌ی دانشجوها جور کن، نه با حرف دیگران."},"type":"explain","id":"c-x04-l3-e","course":"ielts-exams","exam":"exam-04","unit":"x04-l3"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 3","title":{"en":"Offices of the future","tr":"Geleceğin ofisleri","fa":"دفترهای کار آینده"},"timed":7,"ctx":["L3-humanities"],"script":[{"who":"Lachlan","line":"So, Shona, we've got ten minutes for this presentation on offices of the future. Shall we start by agreeing why we picked the topic? Professor Quaid will ask."},{"who":"Shona","line":"For me it was that article we both read, about city-centre offices sitting half empty since people started working from home. It made me wonder what offices are actually for now."},{"who":"Lachlan","line":"Same here. I'd thought my part-time job might give us some ideas, but it's in a warehouse, so not really. And it wasn't on the list of suggested topics, which is why I wanted to check with the professor first."},{"who":"Shona","line":"Right. How should we organise it? We could each do half, but then it might feel like two separate talks."},{"who":"Lachlan","line":"What about going through it in time order? How offices looked in the past, what's happening now, and then our predictions."},{"who":"Shona","line":"Yes, past, present and future. That gives it a clear shape, and we can both speak in every section."},{"who":"Lachlan","line":"And for visuals, I was thinking of a couple of short video clips. There are some great ones online."},{"who":"Shona","line":"They'd eat into our ten minutes, though, and if the sound doesn't work we'd lose even more time. Photos of real offices would be safer, and they'd make the same point."},{"who":"Lachlan","line":"Fair enough. Photos it is. We can still add a chart or two if we need numbers."},{"who":"Shona","line":"Let's also leave a couple of minutes at the end for questions from the audience. Last time we ran out of time and had to rush the ending."},{"who":"Lachlan","line":"Good point. I'll time us when we rehearse, and we can cut something if we're running over."},{"who":"Shona","line":"OK. Now, the main section: the features we expect to see. Let's go through our list and agree what we'll say about each one."},{"who":"Lachlan","line":"Hot-desking first, where nobody has their own desk. I don't think we need to present that as a prediction. It's already common in most big companies."},{"who":"Shona","line":"True, it's hardly the future any more. What about roof gardens? Some people say they're just for show, to impress visitors."},{"who":"Lachlan","line":"Maybe, but the research we found says staff who spend even ten minutes outside at lunchtime feel calmer. So I'd say the main point is that they help people relax."},{"who":"Shona","line":"Agreed. Then sleep pods, those little capsules where you can have a nap."},{"who":"Lachlan","line":"Honestly, I think they're a gimmick. A couple of tech firms put them in and got a lot of press coverage, but I can't see them lasting. It's a fashion that will pass."},{"who":"Shona","line":"I suspect you're right. Standing desks are different, though. People claim they're much healthier than sitting."},{"who":"Lachlan","line":"The evidence is mixed, isn't it? Some studies found benefits, others found that standing all day causes its own problems. I'd say the honest answer is that more research is needed."},{"who":"Shona","line":"Yes, let's say that. Smart lighting, the kind that switches off when a room is empty, is an easy one. Its main advantage is that it saves energy, and some firms have cut their electricity bills a lot."},{"who":"Lachlan","line":"Some people find it annoying when the lights go off while they're sitting still, but that's a small point. Saving energy is the main thing."},{"who":"Shona","line":"What about on-site childcare? I love the idea. Parents could bring their children to work."},{"who":"Lachlan","line":"It would be popular, but realistically it's only something big employers can do. For a small company, the cost of staff and insurance would be far too high."},{"who":"Shona","line":"So, too expensive for small firms. And the last one, quiet booths: small, soundproof rooms for phone calls or focused work."},{"who":"Lachlan","line":"I think they're the most useful thing on the list. Open-plan offices are so noisy, and the booths give people somewhere to concentrate. Older employees ask for them a lot, apparently, but they help everyone focus, whatever their age."},{"who":"Shona","line":"Good. So their main benefit is better concentration. Right, I'll start drafting the slides for the past and present sections tonight."},{"who":"Lachlan","line":"And I'll find the photos. Let's meet on Thursday to rehearse."}],"groups":[{"instruction":"Questions 21-23. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":21,"kind":"mcq","prompt":"Why did the students choose this topic?","options":["A It was suggested by their professor.","B An article made them think about it.","C Lachlan’s job gave them ideas."],"correct":1,"evidence":"it was that article we both read","why":{"en":"\"It was that article we both read\" about empty offices. Lachlan’s job is in a warehouse, and the topic was not on the list.","tr":"\"İkimizin de okuduğu o makaleydi\", boş ofisler hakkında. Lachlan’ın işi bir depoda ve konu listede yoktu.","fa":"«همان مقاله‌ای بود که هر دو خواندیم» درباره‌ی دفترهای خالی. کار لاکلن در یک انبار است و موضوع در فهرست نبود."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":22,"kind":"mcq","prompt":"How will they organise the presentation?","options":["A Each student will present one half.","B It will be organised in time order, from past to future.","C It will compare offices in different countries."],"correct":1,"evidence":"past, present and future","why":{"en":"Each doing half \"might feel like two separate talks\". They agree on \"past, present and future\".","tr":"Her birinin yarısını yapması \"iki ayrı konuşma gibi\" gelebilir. \"Geçmiş, şimdi ve gelecek\"te anlaşıyorlar.","fa":"اینکه هر کدام نصفش را بگویند «شاید شبیه دو صحبت جدا شود». روی «گذشته، حال و آینده» توافق می‌کنند."},"trap":["TR-ruledout","PARA-opinion"]},{"n":23,"kind":"mcq","prompt":"What do they decide to use as visuals?","options":["A short video clips","B pictures of actual workplaces","C charts only"],"correct":1,"evidence":"Photos of real offices would be safer","why":{"en":"The clips \"would eat into our ten minutes\". \"Fair enough. Photos it is.\" Charts may be added, but not only charts.","tr":"Videolar \"on dakikamızı yer\". \"Peki. Fotoğraf olsun.\" Grafik eklenebilir ama yalnızca grafik değil.","fa":"کلیپ‌ها «از ده دقیقه‌مان می‌خورند». «باشه. پس عکس». شاید نمودار هم اضافه کنند، اما نه فقط نمودار."},"trap":["TR-ruledout"]}]},{"instruction":"Questions 24-30. What do the students say about each of the following features of future offices? Choose SEVEN answers from the box and write the correct letter, A-I, next to Questions 24-30.","qtype":"matching","bank":["A It is already common.","B It is too expensive for small companies.","C It may be bad for staff health.","D It saves energy.","E It is popular mainly with older employees.","F It will not stay popular for long.","G It improves concentration.","H It helps staff relax.","I It needs more research."],"questions":[{"n":24,"kind":"match","prompt":"hot-desking","correct":0,"evidence":"It's already common in most big companies","why":{"en":"\"It’s already common in most big companies... hardly the future any more.\"","tr":"\"Büyük şirketlerin çoğunda zaten yaygın... artık pek gelecek sayılmaz.\"","fa":"«همین حالا در بیشتر شرکت‌های بزرگ رایج است... دیگر چیز آینده نیست»."},"trap":["TR-paraphrase"]},{"n":25,"kind":"match","prompt":"roof gardens","correct":7,"evidence":"they help people relax","why":{"en":"\"Some people say they’re just for show\", but the students agree \"they help people relax\".","tr":"\"Bazıları sadece gösteriş için diyor\" ama öğrenciler \"insanların rahatlamasına yardım ettiğinde\" anlaşıyor.","fa":"«بعضی‌ها می‌گویند فقط برای نمایش‌اند»، اما دانشجوها توافق می‌کنند که «به آرامش آدم‌ها کمک می‌کنند»."},"trap":["TR-ruledout","PARA-opinion"]},{"n":26,"kind":"match","prompt":"sleep pods","correct":5,"evidence":"It's a fashion that will pass","why":{"en":"\"A gimmick... I can’t see them lasting. It’s a fashion that will pass.\"","tr":"\"Bir numara... kalıcı olacaklarını sanmıyorum. Geçici bir moda.\"","fa":"«یک ترفند... فکر نمی‌کنم دوام بیاورند. مدی است که می‌گذرد»."},"trap":["TR-paraphrase"]},{"n":27,"kind":"match","prompt":"standing desks","correct":8,"evidence":"more research is needed","why":{"en":"\"People claim they’re much healthier\", but \"the evidence is mixed\": more research is needed. C is not their conclusion.","tr":"\"İnsanlar çok daha sağlıklı olduklarını iddia ediyor\" ama \"kanıtlar çelişkili\": daha fazla araştırma gerekiyor. C onların vardığı sonuç değil.","fa":"«مردم ادعا می‌کنند خیلی سالم‌ترند»، اما «شواهد ضدونقیض است»: پژوهش بیشتری لازم است. C نتیجه‌ی آن‌ها نیست."},"trap":["TR-ruledout"]},{"n":28,"kind":"match","prompt":"smart lighting","correct":3,"evidence":"Its main advantage is that it saves energy","why":{"en":"Some find it annoying, \"but that’s a small point. Saving energy is the main thing.\"","tr":"Bazıları rahatsız oluyor \"ama bu küçük bir ayrıntı. Asıl önemli olan enerji tasarrufu.\"","fa":"بعضی‌ها از آن کلافه می‌شوند، «اما این نکته‌ی کوچکی است. اصلش صرفه‌جویی در انرژی است»."},"trap":["TR-paraphrase"]},{"n":29,"kind":"match","prompt":"on-site childcare","correct":1,"evidence":"it's only something big employers can do","why":{"en":"\"For a small company, the cost... would be far too high\": too expensive for small firms.","tr":"\"Küçük bir şirket için maliyet... çok fazla olurdu\": küçük firmalar için fazla pahalı.","fa":"«برای یک شرکت کوچک هزینه‌اش... خیلی زیاد می‌شود»: برای شرکت‌های کوچک خیلی گران است."},"trap":["TR-paraphrase"]},{"n":30,"kind":"match","prompt":"quiet booths","correct":6,"evidence":"the booths give people somewhere to concentrate","why":{"en":"Older employees ask for them (E is a detail), \"but they help everyone focus\": better concentration.","tr":"Yaşlı çalışanlar istiyor (E bir ayrıntı) \"ama herkesin odaklanmasına yardım ediyorlar\": daha iyi konsantrasyon.","fa":"کارمندان مسن‌تر درخواستش می‌کنند (E یک جزئیات است)، «اما به تمرکز همه کمک می‌کند»: تمرکز بهتر."},"trap":["TR-ruledout","TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Shona":{"accent":"Scottish","gender":"F","tts":{"engine":"piper","voice":"en_GB-alba-medium"},"role":"Student"},"Lachlan":{"accent":"Northern English","gender":"M","tts":{"engine":"piper","voice":"en_GB-northern_english_male-medium"},"role":"Student"}},"sequence":[{"type":"announcer","text":"Part 3. You will hear two students, Shona and Lachlan, preparing a presentation about offices of the future. First, you have some time to look at Questions 21 to 23."},{"type":"pause","seconds":30,"note":"reading time, Questions 21-23"},{"type":"announcer","text":"Now listen carefully and answer Questions 21 to 23."},{"type":"sfx","note":"student common room: low background voices"},{"type":"lines","from":0,"to":10},{"type":"announcer","text":"Before you hear the rest of the discussion, you have some time to look at Questions 24 to 30."},{"type":"pause","seconds":30,"note":"reading time, Questions 24-30"},{"type":"announcer","text":"Now listen and answer Questions 24 to 30."},{"type":"lines","from":11,"to":26},{"type":"announcer","text":"That is the end of Part 3. You now have half a minute to check your answers.","after":30}]},"id":"c-x04-l3-d","course":"ielts-exams","exam":"exam-04","unit":"x04-l3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"A \"gimmick\" is...","options":["a long-term solution","a scientific study","something used to attract attention, with little real value"],"correct":2,"why":{"en":"A gimmick gets attention but is not really useful.","tr":"Gimmick dikkat çeker ama gerçekten işe yaramaz.","fa":"gimmick توجه جلب می‌کند اما واقعاً مفید نیست."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"studies do not agree\"?","options":["the evidence is clear","the evidence is mixed","there is plenty of evidence"],"correct":1,"why":{"en":"Mixed evidence = some results point one way, some the other.","tr":"Mixed evidence = bazı sonuçlar bir yönü, bazıları öbür yönü gösterir.","fa":"mixed evidence یعنی بعضی نتیجه‌ها یک طرف را نشان می‌دهند و بعضی طرف دیگر را."}},{"tests":"method","point":2,"prompt":"One student suggests an idea and the other says \"That would take too long.\" The first says \"True.\" What has happened?","options":["The idea has been dropped","The idea has been accepted","They have not decided yet"],"correct":0,"why":{"en":"A problem, then agreement with the problem: the idea is dropped.","tr":"Bir sorun, sonra soruna katılma: fikir bırakıldı.","fa":"یک مشکل و بعد موافقت با آن مشکل: ایده کنار گذاشته شد."}},{"tests":"trap","point":3,"prompt":"\"Apparently teenagers love these phones, but what matters most is how long the battery lasts.\" What is the main point about the phones?","options":["that teenagers love them","their price","their battery life"],"correct":2,"why":{"en":"\"Apparently\" gives a detail; \"what matters most\" gives the main point.","tr":"\"Apparently\" bir ayrıntı verir; \"what matters most\" ana noktayı verir.","fa":"«apparently» یک جزئیات می‌دهد؛ «what matters most» نکته‌ی اصلی را."}},{"tests":"method","point":1,"prompt":"Seven questions and a box of nine letters, \"Choose SEVEN answers\". How many letters will be left over?","options":["none","two","seven"],"correct":1,"why":{"en":"Nine options, seven used once each: two are extra.","tr":"Dokuz seçenek, yedisi birer kez kullanılır: ikisi fazla.","fa":"نُه گزینه، هفت تا هر کدام یک بار: دو تا اضافه‌اند."}}],"id":"c-x04-l3-x","course":"ielts-exams","exam":"exam-04","unit":"x04-l3"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
